import {pickGreeting} from './greetings.js';
import {nextBirthday, daysUntil, publicPeople, validatePerson} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const months=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const today=new Date();today.setHours(0,0,0,0);
const fmt=d=>d.toLocaleDateString('es-AR',{day:'numeric',month:'long'});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let published=[],people=[],loading=true,loadError='';
let view='home',mode='list',calendarMonth=today.getMonth(),calendarYear=today.getFullYear();
function rebuild(){people=published;render()}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function sorted(){return people.map(p=>({...p,next:nextBirthday(p,today),days:daysUntil(p,today)})).sort((a,b)=>a.days-b.days||a.name.localeCompare(b.name,'es'))}
function initials(name){return name.split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('')}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
const art='<div class="hero-art" aria-hidden="true"><div class="halo"></div><span class="spark s1">✦</span><span class="spark s2">✧</span><span class="spark s3">✳</span><span class="spark s4">✦</span><div class="cake"><div class="cake-base"></div><div class="cake-top"></div><div class="frost"></div><div class="frost second"></div><div class="candle"><div class="flame"></div></div></div><span class="art-caption">un día para celebrar</span></div>';
function render(){
 const all=sorted(),birthdays=all.filter(p=>p.days===0),next=all[0];
 $('#nav-count').textContent=people.length;
 $('#today-label').textContent=today.toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 $('#hero').innerHTML='<div class="hero-copy"><span class="hero-tag">'+(birthdays.length?'✦ HOY SOPLAMOS VELITAS':next?'✦ EL PRÓXIMO GRAN DÍA':'✦ EMPECEMOS A CELEBRAR')+'</span><h2>'+(birthdays.length?'¡Hoy cumple '+esc(birthdays[0].name.split(' ')[0])+'! <span>✧</span>':next?'Se viene el cumple de '+esc(next.name.split(' ')[0])+'<span>.</span>':'Cada cumpleaños merece<br>su lugar<span>.</span>')+'</h2><p>'+(birthdays.length?'Un día especial merece un lindo saludo.'+(birthdays.length>1?' Y '+(birthdays.length-1)+' persona(s) más también cumplen hoy.':'')+'<br>Tomate un momento para alegrarle el día.':next?'El '+fmt(next.next)+', en '+next.days+' día(s).<br>Un buen momento para preparar un lindo saludo.':'Los cumpleaños del equipo aparecerán acá cuando estén publicados.')+'</p><div class="actions">'+(next?'<button class="btn" id="hero-greet">↗ '+(birthdays.length?'Enviar un saludo':'Preparar un saludo')+'</button>':'')+'</div></div>'+art;
 if(next){$('#hero-greet').onclick=()=>greet(next)}
 $('#stats').innerHTML=[['✧',birthdays.length,'Cumplen hoy'],['▦',all.filter(p=>p.month===today.getMonth()+1).length,'Cumpleaños este mes'],['♡',people.length,'Personas para celebrar']].map(([icon,n,label])=>'<div class="stat"><div class="stat-icon">'+icon+'</div><div><strong>'+n+'</strong><small>'+label+'</small></div></div>').join('');
 $('#list-title').innerHTML=view==='calendar'?'Calendario <span>▦</span>':'Lo que se viene <span>↗</span>';
 $('#list-description').textContent='Un pequeño saludo. Un gran gesto.';
 $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 renderResults();
}
function filtered(){const query=$('#search').value.trim().toLocaleLowerCase('es'),month=Number($('#month-filter').value);return sorted().filter(p=>(!month||p.month===month)&&p.name.toLocaleLowerCase('es').includes(query))}
function renderResults(){const rows=filtered();$('#result-count').textContent=rows.length+' personas';$$('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));
 if(mode==='calendar'){renderCalendar(rows);return}
 if(!rows.length){$('#results').innerHTML='<div class="empty"><span>✧</span>'+(loading?'Cargando cumpleaños…':loadError||'No encontramos cumpleaños. Probá con otro nombre o mes.')+'</div>';return}
 $('#results').innerHTML='<div class="table"><div class="table-head"><span>PERSONA</span><span>CUMPLEAÑOS</span><span>CUÁNDO</span><span style="text-align:right">UN PEQUEÑO GESTO</span></div>'+rows.map((p,i)=>'<article class="person-row"><div class="person"><span class="avatar tone'+i%5+'">'+esc(initials(p.name))+'</span><div><strong>'+esc(p.name)+'</strong><small>Equipo Arredo</small></div></div><span class="birthday-date">'+fmt(new Date(2000,p.month-1,p.day))+'</span><span class="when '+(p.days===0?'today':'')+'">'+(p.days===0?'✦ ¡Es hoy!':p.days===1?'Mañana':'En '+p.days+' días')+'</span><div class="row-actions"><button class="small-btn" data-greet="'+esc(p.id)+'">↗ Saludar</button></div></article>').join('')+'</div>';
 $$('[data-greet]').forEach(b=>b.onclick=()=>greet(people.find(p=>p.id===b.dataset.greet)));
}
function renderCalendar(rows){const start=(new Date(calendarYear,calendarMonth,1).getDay()+6)%7,total=new Date(calendarYear,calendarMonth+1,0).getDate();let html='<div class="calendar-top"><button class="btn white" id="prev-month" aria-label="Mes anterior">←</button><strong>'+months[calendarMonth]+' '+calendarYear+'</strong><button class="btn white" id="next-month" aria-label="Mes siguiente">→</button></div><div class="calendar-grid">'+['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'].map(d=>'<div class="week-day">'+d+'</div>').join('');for(let i=0;i<start;i++)html+='<div class="day blank"></div>';for(let d=1;d<=total;d++)html+='<div class="day '+(d===today.getDate()&&calendarMonth===today.getMonth()&&calendarYear===today.getFullYear()?'current':'')+'">'+d+rows.filter(p=>p.day===d&&p.month===calendarMonth+1).map(p=>'<button class="calendar-person" data-person="'+esc(p.id)+'">✦ '+esc(p.name)+'</button>').join('')+'</div>';$('#results').innerHTML=html+'</div>';$('#prev-month').onclick=()=>shiftMonth(-1);$('#next-month').onclick=()=>shiftMonth(1);$$('[data-person]').forEach(b=>b.onclick=()=>greet(people.find(p=>p.id===b.dataset.person)))}
function shiftMonth(amount){const d=new Date(calendarYear,calendarMonth+amount,1);calendarYear=d.getFullYear();calendarMonth=d.getMonth();renderResults()}
const lastGreetings=new Map();
function greet(p){openDialog('<h2>Un saludo para '+esc(p.name.split(' ')[0])+' ✦</h2><p>Prepará tu mensaje y elegí cómo saludar.</p>'+(p.email?'<p class="recipient">Para: <strong>'+esc(p.email)+'</strong></p>':'')+'<label class="field" for="greeting">Tu mensaje</label><textarea id="greeting"></textarea><div class="actions"><a class="btn" id="mail-link">↗ Abrir mi correo</a><a class="btn white" id="teams-link" target="_blank" rel="noopener noreferrer">Abrir chat en Teams</a><button class="btn white" id="another-greeting">↻ Otro saludo</button><button class="btn white" id="copy-greeting">Copiar saludo</button></div><p class="help">'+(p.email?'Se abre un borrador con el destinatario y el mensaje. Vos lo revisás y lo enviás desde tu cuenta.':'Todavía no hay un correo registrado para esta persona. Completá el destinatario o copiá el saludo y buscala en Teams.')+'</p>');const choose=()=>{const selected=pickGreeting(p.name,lastGreetings.get(p.id));lastGreetings.set(p.id,selected.index);$('#greeting').value=selected.text};choose();const update=()=>{const message=$('#greeting').value;$('#mail-link').href='mailto:'+(p.email?encodeURIComponent(p.email):'')+'?subject='+encodeURIComponent('¡Feliz cumpleaños, '+p.name.split(' ')[0]+'! 🎂')+'&body='+encodeURIComponent(message);$('#teams-link').href=p.email?'https://teams.microsoft.com/l/chat/0/0?users='+encodeURIComponent(p.email)+'&message='+encodeURIComponent(message):'https://teams.microsoft.com/'};update();$('#greeting').oninput=update;$('#another-greeting').onclick=()=>{choose();update()};$('#copy-greeting').onclick=async()=>{try{await navigator.clipboard.writeText($('#greeting').value);toast('Saludo copiado. Buscá a '+p.name+' en Teams.')}catch{toast('Seleccioná el texto del saludo y copialo.')}}}
async function loadPublished(){loading=true;loadError='';render();try{const response=await fetch('./birthdays.json',{cache:'no-store'});if(!response.ok)throw Error('No pudimos actualizar la lista del equipo. Intentá otra vez.');const json=await response.json();if(!Array.isArray(json.people))throw Error('La lista del equipo no tiene un formato válido.');json.people.forEach(p=>validatePerson(p));published=publicPeople(json.people,{includeEmail:true});}catch(error){loadError=error.message;toast(loadError)}finally{loading=false;rebuild()}}
months.forEach((month,i)=>$('#month-filter').insertAdjacentHTML('beforeend','<option value="'+(i+1)+'">'+month[0].toUpperCase()+month.slice(1)+'</option>'));
$('#search').oninput=renderResults;$('#month-filter').onchange=()=>{if($('#month-filter').value)calendarMonth=Number($('#month-filter').value)-1;renderResults()};$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;mode=view==='calendar'?'calendar':'list';$('#search').value='';$('#month-filter').value='';render()});$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;view=mode==='calendar'?'calendar':'home';render()});render();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&new Date().toDateString()!==today.toDateString())location.reload()});

loadPublished();
